SELECT CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM invoice_title_subject its
INNER JOIN invoice_subject s ON s.id = its.subject_id AND s.status = 'ENABLED' AND s.deleted = 0
INNER JOIN ding_employee current_employee ON current_employee.id = #{employeeId}
WHERE its.title_id = #{titleId}
